/*! Universal Admin Notification Popup | Modified from Plus UI */
"use strict";
((e, t, n) => {
    // Hàm set cookie
    function setCookie(name, value, hours) {
        let exp = new Date();
        exp.setTime(exp.getTime() + 36e5 * hours);
        n.cookie = name + "=" + encodeURIComponent(value) + ";expires=" + exp.toUTCString() + ";path=/";
    }

    // Hàm get cookie
    function getCookie(name) {
        let regex = RegExp("(^| )" + name + "=([^;]+)"),
            match = n.cookie.match(regex);
        return match ? decodeURIComponent(match[2]) : null;
    }

    // Nếu cookie tồn tại thì thoát (đã đóng trước đó)
    if (getCookie("hAn") === "true") return;

    // Lấy tên admin từ .nm (nếu có)
    const adminEl = n.querySelector(".nm");
    let adminName = "";
    if (adminEl) {
        let txt = (adminEl.dataset && adminEl.dataset.text || "").trim();
        if (txt) adminName = txt;
    }

    // Popup wrapper
    const wrp = n.createElement("div");
    wrp.className = "admin-wrapperX";
    wrp.innerHTML = `
    <div class='papW admin-notices'>
      <div class='papB'>
        <div class='papT'>Dear Admin${adminName ? " ("+adminName+")" : ""},</div>
        <div class='papC'>
          A new version of <strong>UI Theme</strong> is available.<br/>
          Please update to enjoy the latest features and improvements.
          <br/><em style="color:#555;font-size:13px;margin-top:12px;">
          (Note: This message is only visible to the admin of this site.)</em>
          <div class="btnF">
            <a class='button ln close-btn' role="button">Close</a>
            <a class='button update-btn' href='https://t.me/sakevn' target="_blank" rel="noopener">Update Now!</a>
          </div>
        </div>
      </div>
    </div>
    <style>
      .button{--linkB:#1976d2;flex:1;text-align:center;display:inline-flex;
        justify-content:center;align-items:center;gap:8px;padding:10px 12px;
        outline:0;border:0;border-radius:6px;line-height:20px;color:#fff;
        background:#3740ff;font-size:14px;white-space:nowrap;min-width:120px;
        text-decoration:none}
      .button.ln{background:0 0;border:1px solid var(--linkB,#3740ff);
        color:var(--linkB,#3740ff)}
      .button.ln:hover{border-color:#3740ff;box-shadow:0 0 0 1px #3740ff inset}
      .btnF{display:flex;justify-content:space-between;gap:12px;margin-top:12px}
      @keyframes fadeOut{from{opacity:1}to{opacity:0}}
    </style>`;
    
    n.body.appendChild(wrp);

    // Nút đóng
    const closeBtn = wrp.querySelector(".close-btn");
    closeBtn && closeBtn.addEventListener("click", function() {
        setCookie("hAn", "true", 24);
        wrp.style.animation = "fadeOut 0.3s forwards";
        setTimeout(() => wrp.remove(), 300);
    });

})(window, window, document);
